mapper.select:
SELECT c.id, c.version, c.memo_id, c.loop_item_id, c.comment_date, c.comment_text, c.img_arr, c.create_time, c.update_time, ( SELECT COUNT(*) FROM loop_memo_item_comment c2 WHERE c2.loop_item_id = c.loop_item_id ) AS comment_total FROM loop_memo_item_comment c WHERE c.loop_item_id IN
#{loopItemId}
AND ( SELECT COUNT(*) FROM loop_memo_item_comment c3 WHERE c3.loop_item_id = c.loop_item_id AND ( c3.comment_date > c.comment_date OR (c3.comment_date = c.comment_date AND c3.id > c.id) ) ) < #{limitSize} ORDER BY c.loop_item_id, c.comment_date DESC, c.id DESC
